// Find which BUC sheet tab contains this appointment ID
const SHEET_ID = '1y-tME_4wRhoFeLozOcnfNflznECa1Qp6NAGUeM2cKVc';
const TABS = ["Tim's Team", "Mark's Team", "Mikey's Team", "Ilya's Team", "Joey's Team"];

const body = $json.body || $json;
const apptId = (body.appointmentId || '').trim();

if (!apptId) {
  return [{ json: { ...body, _found: false, _error: 'No appointmentId in payload' } }];
}

function parseCSV(text) {
  return text.split('\n').map(line => {
    const cols = [];
    let cur = '', inQuote = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') { inQuote = !inQuote; }
      else if (ch === ',' && !inQuote) { cols.push(cur.trim()); cur = ''; }
      else { cur += ch; }
    }
    cols.push(cur.trim());
    return cols;
  });
}

for (const tab of TABS) {
  const url = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(tab)}`;
  let text;
  try {
    text = await $helpers.httpRequest({ url, method: 'GET' });
  } catch (e) {
    continue;
  }
  if (typeof text !== 'string') text = JSON.stringify(text);

  const rows = parseCSV(text);
  if (rows.length < 2) continue;

  const headers = rows[0].map(h => h.replace(/^"|"$/g, '').trim());
  const apptIdCol = headers.indexOf('Appointment ID');
  if (apptIdCol === -1) continue;

  for (let i = 1; i < rows.length; i++) {
    const cell = (rows[i][apptIdCol] || '').replace(/^"|"$/g, '').trim();
    if (cell === apptId) {
      return [{
        json: {
          appointmentId:  body.appointmentId,
          contactId:      body.contactId,
          locationId:     body.locationId,
          triggeredAt:    body.triggeredAt,
          callStatus:     body.callStatus,
          callOutcome:    body.callOutcome,
          cashCollected:  body.cashCollected,
          totalValue:     body.totalValue,
          leadQuality:    body.leadQuality,
          callQuality:    body.callQuality,
          recording:      body.recording,
          notes:          body.notes,
          jerryGrade:     body.jerryGrade,
          jerryCoachNote: body.jerryCoachNote,
          _found: true,
          _tab: tab
        }
      }];
    }
  }
}

return [{
  json: {
    appointmentId: apptId,
    _found: false,
    _error: `Appointment ID not found in any tab: ${apptId}`
  }
}];
